const weather = $('Get Alsip weather').first().json;
const reports = $('Summarize evening reports').first().json;
const escapeHtml = (value) => String(value ?? '')
  .replaceAll('&', '&amp;')
  .replaceAll('<', '&lt;')
  .replaceAll('>', '&gt;')
  .replaceAll('"', '&quot;')
  .replaceAll("'", '&#039;');
const safeUrl = (value) => /^https?:\/\//i.test(String(value ?? '')) ? String(value) : '#';
const markdownLabel = (value) => String(value ?? '').replace(/[\[\]()*_`~>|]/g, '').trim();
const discordUrl = (value) => safeUrl(value).replaceAll('(', '%28').replaceAll(')', '%29');
const asTime = (value) => {
  const time = Date.parse(value ?? '');
  return Number.isFinite(time) ? time : 0;
};

const entries = items
  .map(({ json }) => ({
    title: String(json.title ?? '').trim(),
    link: safeUrl(json.link),
    creator: String(json.creator ?? json.author ?? json['dc:creator'] ?? '').trim(),
    published: json.isoDate ?? json.pubDate ?? '',
  }))
  .filter((entry) => entry.title && entry.link !== '#')
  .sort((left, right) => asTime(right.published) - asTime(left.published));

const reddit = entries.filter((entry) => entry.link.includes('reddit.com')).slice(0, 4);
const videosByCreator = new Map();
for (const entry of entries.filter((candidate) => !candidate.link.includes('reddit.com'))) {
  const creator = entry.creator || 'Gaming video';
  const creatorEntries = videosByCreator.get(creator) ?? [];
  if (creatorEntries.length < 2) creatorEntries.push(entry);
  videosByCreator.set(creator, creatorEntries);
}
const videos = [...videosByCreator.entries()].flatMap(([creator, creatorEntries]) =>
  creatorEntries.map((entry) => ({ ...entry, creator }))
);

const current = weather.current ?? {};
const daily = weather.daily ?? {};
const currentTemp = Math.round(Number(current.temperature_2m ?? 0));
const feelsLike = Math.round(Number(current.apparent_temperature ?? currentTemp));
const high = Math.round(Number(daily.temperature_2m_max?.[0] ?? currentTemp));
const low = Math.round(Number(daily.temperature_2m_min?.[0] ?? currentTemp));
const rainChance = Math.round(Number(daily.precipitation_probability_max?.[0] ?? 0));
const weatherCode = Number(current.weather_code ?? daily.weather_code?.[0] ?? -1);
const weatherLabels = {
  0: 'Clear', 1: 'Mostly clear', 2: 'Partly cloudy', 3: 'Overcast',
  45: 'Foggy', 48: 'Icy fog', 51: 'Light drizzle', 53: 'Drizzle',
  55: 'Heavy drizzle', 61: 'Light rain', 63: 'Rain', 65: 'Heavy rain',
  71: 'Light snow', 73: 'Snow', 75: 'Heavy snow', 80: 'Rain showers',
  81: 'Rain showers', 82: 'Heavy showers', 95: 'Thunderstorms',
};
const conditions = weatherLabels[weatherCode] ?? 'Mixed conditions';
const stayInLine = rainChance >= 50
  ? `A ${rainChance}% rain chance makes this a strong stay-in-and-play night.`
  : currentTemp <= 35
    ? `It is ${currentTemp}° outside. The backlog wins tonight.`
    : 'Weather is not trapping you inside, but the backlog might.';

const chicagoDate = new Intl.DateTimeFormat('en-US', {
  timeZone: 'America/Chicago', month: 'short', day: 'numeric', year: 'numeric',
}).format(new Date());
const formatPublished = (value) => {
  if (!asTime(value)) return '';
  return new Intl.DateTimeFormat('en-US', {
    timeZone: 'America/Chicago', month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit',
  }).format(new Date(value));
};
const card = (entry, badge) => `
  <a href="${escapeHtml(entry.link)}" style="display:block;text-decoration:none;color:#f4f1ff;background:#17131f;border:1px solid #332943;border-radius:12px;padding:14px 16px;margin:0 0 10px">
    <span style="display:inline-block;color:#d8b65c;font:700 11px/1.2 monospace;letter-spacing:.08em;text-transform:uppercase;margin-bottom:7px">${escapeHtml(badge)}</span>
    <span style="display:block;font:600 16px/1.35 system-ui,-apple-system,sans-serif">${escapeHtml(entry.title)}</span>
    <span style="display:block;color:#91879f;font:12px/1.4 system-ui,-apple-system,sans-serif;margin-top:6px">${escapeHtml(formatPublished(entry.published))}</span>
  </a>`;
const reportCard = (eyebrow, headline, detail, url, linkText) => `
  <div style="background:#17131f;border:1px solid #332943;border-radius:12px;padding:16px;margin:0 0 10px">
    <div style="color:#d8b65c;font:700 11px/1.2 monospace;letter-spacing:.1em">${escapeHtml(eyebrow)}</div>
    <div style="font:700 18px/1.35 system-ui,-apple-system,sans-serif;margin-top:7px">${escapeHtml(headline)}</div>
    <div style="color:#c2b9cf;font:14px/1.5 system-ui,-apple-system,sans-serif;margin-top:5px">${escapeHtml(detail)}</div>
    <a href="${escapeHtml(url)}" style="display:inline-block;color:#cba6f7;font:600 13px/1.4 system-ui,-apple-system,sans-serif;margin-top:9px">${escapeHtml(linkText)} →</a>
  </div>`;

const fleet = reports.fleet ?? {};
const deployment = reports.deployment ?? {};
const fleetHealthy = Number(fleet.healthy ?? 0);
const fleetTotal = Number(fleet.total ?? 0);
const securityHealthy = Number(fleet.securityHealthy ?? 0);
const securityTotal = Number(fleet.securityTotal ?? 0);
const securityHeadline = fleet.socHealthy
  ? `${securityHealthy}/${securityTotal} security consoles reachable`
  : 'SOC dashboard is unreachable';
const securityDetail = `Fleet services ${fleetHealthy}/${fleetTotal} reachable. Aggregates only; no raw alerts, logs, or IP addresses leave the SOC.`;
const deploymentHeadline = !deployment.available
  ? 'Hydra production report unavailable'
  : deployment.failed > 0
    ? `${deployment.failed} production job${deployment.failed === 1 ? '' : 's'} failed`
    : deployment.pending > 0
      ? `${deployment.succeeded}/${deployment.total} production jobs built`
      : `All ${deployment.total} production jobs built`;
const revisionLine = deployment.revision ? `Revision ${deployment.revision}` : 'Revision unavailable';
const deploymentDetail = deployment.available
  ? `${revisionLine} · ${deployment.pending} pending · ${deployment.failed} failed`
  : 'The digest continued with weather and gaming data.';

const newsHtml = reddit.length
  ? reddit.map((entry) => card(entry, 'Reddit gaming')).join('')
  : '<p style="color:#91879f">Reddit had nothing usable this run.</p>';
const videoHtml = videos.length
  ? videos.map((entry) => card(entry, entry.creator)).join('')
  : '<p style="color:#91879f">The video feeds had nothing usable this run.</p>';

const html = `<!doctype html>
<html><body style="margin:0;background:#09070d;color:#f4f1ff">
  <div style="max-width:680px;margin:0 auto;padding:34px 20px 48px">
    <div style="color:#d8b65c;font:700 12px/1.2 monospace;letter-spacing:.18em">GUILDEDTHORN // EVENING DROP</div>
    <h1 style="font:700 34px/1.1 system-ui,-apple-system,sans-serif;margin:12px 0 4px">Evening, Thorn.</h1>
    <p style="color:#91879f;font:14px/1.5 system-ui,-apple-system,sans-serif;margin:0 0 24px">${escapeHtml(chicagoDate)}</p>

    <h2 style="font:700 22px/1.2 system-ui,-apple-system,sans-serif;margin:28px 0 12px">Home ops</h2>
    ${reportCard('SECURITY + FLEET', securityHeadline, securityDetail, 'https://soc.guildedthorn.arpa:3000/', 'Open SIEM')}
    ${reportCard('THORNIXOS PRODUCTION', deploymentHeadline, deploymentDetail, safeUrl(deployment.evaluationUrl), 'Open Hydra evaluation')}

    <div style="background:linear-gradient(135deg,#20152a,#12101a);border:1px solid #49365d;border-radius:16px;padding:20px;margin:28px 0">
      <div style="color:#d8b65c;font:700 11px/1.2 monospace;letter-spacing:.1em">ALSIP TONIGHT</div>
      <div style="font:700 28px/1.25 system-ui,-apple-system,sans-serif;margin-top:8px">${escapeHtml(conditions)} · ${currentTemp}°F</div>
      <div style="color:#c2b9cf;font:14px/1.55 system-ui,-apple-system,sans-serif;margin-top:6px">Feels ${feelsLike}° · High ${high}° · Low ${low}° · Rain ${rainChance}%</div>
      <div style="color:#f4f1ff;font:15px/1.55 system-ui,-apple-system,sans-serif;margin-top:12px">${escapeHtml(stayInLine)}</div>
    </div>

    <h2 style="font:700 22px/1.2 system-ui,-apple-system,sans-serif;margin:28px 0 12px">Tonight's gaming pulse</h2>
    ${newsHtml}
    <h2 style="font:700 22px/1.2 system-ui,-apple-system,sans-serif;margin:32px 0 12px">Fresh from your channels</h2>
    ${videoHtml}
    <p style="color:#665d72;font:12px/1.5 system-ui,-apple-system,sans-serif;margin-top:28px">Curated locally by Loom. Operational data is aggregate-only; no raw SIEM events, log lines, IP addresses, AI summaries, or tracking pixels.</p>
  </div>
</body></html>`;

const discordEntry = (entry, badge) =>
  `• **${markdownLabel(badge)}** — [${markdownLabel(entry.title)}](${discordUrl(entry.link)})`;
const securitySection = [
  `${fleet.socHealthy ? '✅' : '⛔'} SOC dashboard: ${fleet.socHealthy ? 'reachable' : 'unreachable'}`,
  `${securityHealthy === securityTotal ? '✅' : '⚠️'} Security consoles: **${securityHealthy}/${securityTotal} reachable**`,
  `${fleetHealthy === fleetTotal ? '✅' : '⚠️'} Fleet services: **${fleetHealthy}/${fleetTotal} reachable**`,
  '[SIEM](https://soc.guildedthorn.arpa:3000/) · [Cases](https://casebook.guildedthorn.arpa/) · [EDR](https://hound.guildedthorn.arpa/app/index.html)',
].join('\n');
const deploymentSection = [
  `${deployment.failed > 0 ? '⛔' : !deployment.available || deployment.pending > 0 ? '⏳' : '✅'} ${deploymentHeadline}`,
  deploymentDetail,
  `[Open evaluation](${discordUrl(deployment.evaluationUrl)})`,
].join('\n');
const weatherSection = [
  `**${conditions} · ${currentTemp}°F**`,
  `Feels ${feelsLike}° · High ${high}° · Low ${low}° · Rain ${rainChance}%`,
  stayInLine,
].join('\n');
const gamingSection = reddit.length
  ? reddit.map((entry) => discordEntry(entry, 'Reddit')).join('\n')
  : 'No usable Reddit items this run.';
const channelsSection = videos.length
  ? videos.map((entry) => discordEntry(entry, entry.creator)).join('\n')
  : 'No usable video items this run.';

const textLines = [
  `GUILDEDTHORN // EVENING DROP — ${chicagoDate}`,
  '', 'SECURITY + FLEET',
  `SOC dashboard: ${fleet.socHealthy ? 'reachable' : 'unreachable'}`,
  `Security consoles: ${securityHealthy}/${securityTotal} reachable`,
  `Fleet services: ${fleetHealthy}/${fleetTotal} reachable`,
  'SIEM: https://soc.guildedthorn.arpa:3000/',
  '', 'THORNIXOS PRODUCTION',
  deploymentHeadline,
  deploymentDetail,
  safeUrl(deployment.evaluationUrl),
  '', 'ALSIP TONIGHT',
  `${conditions}, ${currentTemp}°F (feels ${feelsLike}°), high ${high}°, low ${low}°, rain ${rainChance}%`,
  stayInLine,
  '', "TONIGHT'S GAMING PULSE",
  ...(reddit.length ? reddit.map((entry) => `- ${entry.title} — ${entry.link}`) : ['- No usable Reddit items this run.']),
  '', 'FRESH FROM YOUR CHANNELS',
  ...(videos.length ? videos.map((entry) => `- [${entry.creator}] ${entry.title} — ${entry.link}`) : ['- No usable video items this run.']),
];

return [{ json: {
  subject: `Thorn's Evening Drop · ${chicagoDate}`,
  html,
  text: textLines.join('\n'),
  itemCount: reddit.length + videos.length,
  severity: reports.severity ?? 'warning',
  fleetHealthy,
  fleetTotal,
  sections: {
    security: securitySection,
    deployment: deploymentSection,
    weather: weatherSection,
    gaming: gamingSection,
    channels: channelsSection,
  },
} }];

const fieldLimit = 1024;
const safeText = (value) => String(value ?? '').replaceAll('@', '@\u200b');
const fit = (value, limit = fieldLimit) => {
  const source = safeText(value).trim();
  if (!source) return 'No usable data this run.';
  if (source.length <= limit) return source;

  const candidate = source.slice(0, limit - 2);
  const lastBreak = candidate.lastIndexOf('\n');
  const cut = lastBreak >= Math.floor(limit * 0.6) ? lastBreak : candidate.length;
  return `${candidate.slice(0, cut).trimEnd()}\n…`;
};

const colors = {
  normal: '#cba6f7',
  warning: '#f9e2af',
  critical: '#f38ba8',
};
const sections = $json.sections ?? {};
const discordEmbed = {
  author: { name: 'GUILDEDTHORN // EVENING DROP' },
  title: fit($json.subject ?? "Thorn's Evening Drop", 256),
  description: 'Your 5:30 PM home-ops, weather, and gaming brief.',
  color: colors[$json.severity] ?? colors.warning,
  fields: [
    { name: '🛡️ Security + fleet', value: fit(sections.security), inline: false },
    { name: '🚀 ThornixOS production', value: fit(sections.deployment), inline: false },
    { name: '🌦️ Alsip tonight', value: fit(sections.weather), inline: false },
    { name: "🎮 Tonight's gaming pulse", value: fit(sections.gaming), inline: false },
    { name: '📺 Fresh from your channels', value: fit(sections.channels), inline: false },
  ],
  footer: {
    text: `Loom · ${Number($json.fleetHealthy ?? 0)}/${Number($json.fleetTotal ?? 0)} services · ${Number($json.itemCount ?? 0)} gaming items · Aggregate-only`,
  },
  timestamp: new Date().toISOString(),
};

return [{ json: { ...$json, discordEmbed } }];

const catalogue = $('Evening report catalogue').all();
const checks = items.map((item, index) => {
  const target = catalogue[index]?.json ?? {};
  const statusCode = Number(item.json.statusCode ?? 0);
  const rawError = item.json.error?.message ?? item.json.error ?? item.json.message ?? '';
  return {
    service: target.service ?? `service-${index + 1}`,
    security: Boolean(target.security),
    statusCode,
    healthy: (statusCode >= 200 && statusCode < 400) || statusCode === 401 || statusCode === 403,
    error: typeof rawError === 'string' ? rawError : JSON.stringify(rawError),
  };
});

const securityChecks = checks.filter((check) => check.security);
const soc = checks.find((check) => check.service === 'SOC · Grafana');
return [{ json: {
  total: checks.length,
  healthy: checks.filter((check) => check.healthy).length,
  failures: checks.filter((check) => !check.healthy).length,
  securityTotal: securityChecks.length,
  securityHealthy: securityChecks.filter((check) => check.healthy).length,
  socHealthy: Boolean(soc?.healthy),
} }];

const parseBody = (value) => {
  if (typeof value !== 'string') return value;
  try { return JSON.parse(value); } catch { return {}; }
};

const response = items[0]?.json ?? {};
const body = parseBody(response.body ?? response);
const evaluations = Array.isArray(body.evals) ? body.evals : [];
const latest = evaluations[0];
const revision = String(latest?.flake ?? '').match(/[0-9a-f]{40}/)?.[0] ?? '';

return [{ json: {
  available: Boolean(latest?.id),
  evaluationId: latest?.id ?? null,
  revision: revision ? revision.slice(0, 8) : '',
  evaluatedAt: Number(latest?.timestamp ?? 0),
  buildsUrl: latest?.id
    ? `https://forge.guildedthorn.arpa/eval/${latest.id}/builds`
    : 'https://forge.guildedthorn.arpa/eval/0/builds',
  evaluationUrl: latest?.id
    ? `https://forge.guildedthorn.arpa/eval/${latest.id}`
    : 'https://forge.guildedthorn.arpa/jobset/thornixos/main',
} }];

const parseBody = (value) => {
  if (typeof value !== 'string') return value;
  try { return JSON.parse(value); } catch { return null; }
};

const fleet = $('Summarize fleet report').first().json;
const metadata = $('Select latest Hydra report').first().json;
const response = items[0]?.json ?? {};
const body = parseBody(response.body ?? response);
const builds = Array.isArray(body) ? body : [];
const expected = [
  'anvil', 'atlas', 'casebook', 'courier', 'forge', 'herald', 'hound',
  'identity', 'loom', 'lure', 'mac', 'mitm', 'nixos', 'oracle', 'pixie',
  'scout', 'sieve', 'soc', 'websites',
].map((host) => `production.${host}`);
const byJob = new Map(builds.map((build) => [build.job, build]));
const states = expected.map((job) => {
  const build = byJob.get(job);
  if (!build) return 'pending';
  if (Number(build.finished) !== 1) return 'pending';
  if (Number(build.buildstatus) !== 0) return 'failed';
  if (!Object.values(build.buildoutputs ?? {}).some((output) => output?.path)) return 'failed';
  return 'succeeded';
});
const buildsAvailable = Boolean(metadata.available) && builds.length > 0;
const deployment = {
  available: buildsAvailable,
  evaluationId: metadata.evaluationId,
  revision: metadata.revision,
  evaluatedAt: metadata.evaluatedAt,
  evaluationUrl: metadata.evaluationUrl,
  total: expected.length,
  succeeded: buildsAvailable ? states.filter((state) => state === 'succeeded').length : 0,
  failed: buildsAvailable ? states.filter((state) => state === 'failed').length : 0,
  pending: buildsAvailable ? states.filter((state) => state === 'pending').length : expected.length,
};

const severity = !fleet.socHealthy || fleet.failures > 0 || deployment.failed > 0
  ? 'critical'
  : !deployment.available || deployment.pending > 0 || fleet.securityHealthy < fleet.securityTotal
    ? 'warning'
    : 'normal';

return [{ json: { fleet, deployment, severity } }];
